-- MIR GPS punch: server-authoritative shifts, job/travel segments, corrections and time bank.
begin;
alter table mir_core.jobs add column if not exists latitude numeric(9,6),add column if not exists longitude numeric(9,6),add column if not exists client_name text not null default '',add column if not exists scheduled_start time;
create table mir_core.punch_settings(organization_id uuid primary key,module_enabled boolean not null default false,gps_enabled boolean not null default true,gps_required boolean not null default false,radius_m integer check(radius_m is null or radius_m between 25 and 10000) default 250,outside_policy text not null default 'review' check(outside_policy in('allow','review','block')),outside_reason_required boolean not null default true,offline_enabled boolean not null default true,auto_break_enabled boolean not null default true,break_threshold_minutes integer not null default 300,break_minutes integer not null default 15,travel_rule text not null default 'separate' check(travel_rule in('separate','departure','arrival','split')),reminders_enabled boolean not null default true,bank_enabled boolean not null default false,bank_multiplier numeric(4,2) not null default 1.0,retention_months integer not null default 84,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table mir_core.punch_shifts(organization_id uuid not null,id uuid not null default gen_random_uuid(),employee_id uuid not null,work_date date not null default current_date,started_at timestamptz not null,ended_at timestamptz,status text not null default 'active' check(status in('active','review','approved','locked')),auto_break_minutes integer not null default 0,source text not null default 'online' check(source in('online','offline')),device_id text not null default '',created_at timestamptz not null default now(),primary key(organization_id,id),foreign key(organization_id,employee_id) references mir_core.memberships(organization_id,user_id),check(ended_at is null or ended_at>=started_at));
create unique index punch_one_active_shift on mir_core.punch_shifts(organization_id,employee_id) where ended_at is null;
create index punch_shifts_employee_date on mir_core.punch_shifts(organization_id,employee_id,work_date desc);
create table mir_core.punch_segments(organization_id uuid not null,id uuid not null default gen_random_uuid(),shift_id uuid not null,job_id uuid,segment_type text not null check(segment_type in('job','travel','warehouse','break')),started_at timestamptz not null,ended_at timestamptz,next_job_id uuid,created_by uuid not null references auth.users(id),primary key(organization_id,id),foreign key(organization_id,shift_id) references mir_core.punch_shifts(organization_id,id),foreign key(organization_id,job_id) references mir_core.jobs(organization_id,id),foreign key(organization_id,next_job_id) references mir_core.jobs(organization_id,id),check(ended_at is null or ended_at>=started_at));
create unique index punch_one_active_segment on mir_core.punch_segments(organization_id,shift_id) where ended_at is null;
create table mir_core.punch_events(organization_id uuid not null,id uuid not null default gen_random_uuid(),shift_id uuid,employee_id uuid not null,job_id uuid,event_type text not null,request_id uuid not null,server_at timestamptz not null default now(),original_at timestamptz,latitude numeric(9,6),longitude numeric(9,6),accuracy_m numeric(9,2),distance_m integer,zone_status text not null default 'unknown' check(zone_status in('inside','outside','unavailable','unknown')),outside_reason text not null default '',device_id text not null default '',source text not null default 'online' check(source in('online','offline')),payload jsonb not null default '{}',primary key(organization_id,id),unique(organization_id,employee_id,request_id),foreign key(organization_id,shift_id) references mir_core.punch_shifts(organization_id,id),foreign key(organization_id,employee_id) references mir_core.memberships(organization_id,user_id),foreign key(organization_id,job_id) references mir_core.jobs(organization_id,id));
create table mir_core.punch_corrections(organization_id uuid not null,id uuid not null default gen_random_uuid(),employee_id uuid not null,shift_id uuid,correction_type text not null,proposed_at timestamptz,proposed_job_id uuid,explanation text not null,attachment_path text,status text not null default 'pending' check(status in('pending','clarification','approved','refused')),original_data jsonb not null default '{}',proposed_data jsonb not null default '{}',changes_overtime boolean not null default false,decided_by uuid references auth.users(id),decision_reason text not null default '',decided_at timestamptz,created_at timestamptz not null default now(),primary key(organization_id,id),foreign key(organization_id,employee_id) references mir_core.memberships(organization_id,user_id),foreign key(organization_id,shift_id) references mir_core.punch_shifts(organization_id,id),foreign key(organization_id,proposed_job_id) references mir_core.jobs(organization_id,id));
create table mir_core.time_periods(organization_id uuid not null,id uuid not null default gen_random_uuid(),label text not null,starts_on date not null,ends_on date not null,status text not null default 'open' check(status in('open','review','approved','locked','reopened')),locked_by uuid references auth.users(id),locked_at timestamptz,reopen_reason text not null default '',primary key(organization_id,id),unique(organization_id,starts_on,ends_on),check(ends_on>=starts_on));
create table mir_core.time_bank_movements(organization_id uuid not null,id uuid not null default gen_random_uuid(),employee_id uuid not null,period_id uuid,quantity numeric(8,2) not null,multiplier numeric(4,2) not null default 1,balance_before numeric(8,2) not null,balance_after numeric(8,2) not null,reason text not null,created_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),created_at timestamptz not null default now(),primary key(organization_id,id),foreign key(organization_id,employee_id) references mir_core.memberships(organization_id,user_id),foreign key(organization_id,period_id) references mir_core.time_periods(organization_id,id));
create table mir_core.punch_audit(organization_id uuid not null,id bigint generated always as identity,actor_id uuid not null references auth.users(id),employee_id uuid,action text not null,entity_type text not null,entity_id uuid,reason text not null default '',payload jsonb not null default '{}',created_at timestamptz not null default now(),primary key(organization_id,id));
do $$declare t text;begin foreach t in array array['punch_settings','punch_shifts','punch_segments','punch_events','punch_corrections','time_periods','time_bank_movements','punch_audit'] loop execute format('alter table mir_core.%I enable row level security',t);execute format('revoke all on mir_core.%I from public,anon,authenticated',t);end loop;end$$;
insert into mir_core.punch_settings(organization_id) select id from mir_core.organizations on conflict do nothing;

create function mir_core.punch_manager(org uuid,member uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,mir_core as $$select mir_core.staff_role(org,member) in('admin','boss','assistant')$$;
create function mir_core.punch_distance_m(lat1 numeric,lon1 numeric,lat2 numeric,lon2 numeric) returns integer language sql immutable as $$select case when lat1 is null or lon1 is null or lat2 is null or lon2 is null then null else round(6371000*2*asin(sqrt(power(sin(radians((lat2-lat1)/2)),2)+cos(radians(lat1))*cos(radians(lat2))*power(sin(radians((lon2-lon1)/2)),2))))::int end$$;
revoke all on function mir_core.punch_manager(uuid,uuid),mir_core.punch_distance_m(numeric,numeric,numeric,numeric) from public,anon;grant execute on function mir_core.punch_manager(uuid,uuid),mir_core.punch_distance_m(numeric,numeric,numeric,numeric) to authenticated;

create function public.mir_punch_snapshot(org uuid,employee uuid default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,mir_core as $$declare target uuid:=coalesce(employee,auth.uid());r text:=mir_core.staff_role(org);settings punch_settings;begin
 if target<>auth.uid() and not mir_core.punch_manager(org) and not(r='chef_equipe' and exists(select 1 from team_members tm join teams t on(t.organization_id,t.id)=(tm.organization_id,tm.team_id) where tm.organization_id=org and tm.user_id=target and t.leader_id=auth.uid() and tm.active)) then raise exception 'Accès punch refusé' using errcode='42501';end if;
 select * into settings from punch_settings where organization_id=org;
 return jsonb_build_object('role',r,'employeeId',target,'enabled',coalesce(settings.module_enabled,false),'settings',case when mir_core.punch_manager(org) then to_jsonb(settings) else jsonb_build_object('gpsEnabled',settings.gps_enabled,'gpsRequired',settings.gps_required,'offlineEnabled',settings.offline_enabled,'bankEnabled',settings.bank_enabled) end,
 'activeShift',(select to_jsonb(s)||jsonb_build_object('segment',(select to_jsonb(g) from punch_segments g where g.organization_id=org and g.shift_id=s.id and g.ended_at is null)) from punch_shifts s where s.organization_id=org and s.employee_id=target and s.ended_at is null),
 'week',coalesce((select jsonb_agg(to_jsonb(s)||jsonb_build_object('segments',(select coalesce(jsonb_agg(to_jsonb(g) order by g.started_at),'[]') from punch_segments g where g.organization_id=org and g.shift_id=s.id)) order by s.work_date desc) from punch_shifts s where s.organization_id=org and s.employee_id=target and s.work_date>=current_date-6),'[]'),
 'corrections',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at desc) from punch_corrections c where c.organization_id=org and (c.employee_id=target or mir_core.punch_manager(org)) and c.status in('pending','clarification')),'[]'),
 'bankBalance',coalesce((select balance_after from time_bank_movements b where b.organization_id=org and b.employee_id=target order by created_at desc limit 1),0));end$$;

create function public.mir_punch_action(org uuid,request_id uuid,action text,job uuid default null,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path=pg_catalog,mir_core as $$declare actor uuid:=auth.uid();settings punch_settings;shift punch_shifts;segment punch_segments;now_at timestamptz:=clock_timestamp();lat numeric;lon numeric;dist integer;zone text:='unknown';source_name text:=case when payload->>'source'='offline' then 'offline' else 'online' end;result jsonb;begin
 if actor is null or mir_core.staff_role(org) is null then raise exception 'Authentification requise' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(org::text||actor::text,0));select * into settings from punch_settings where organization_id=org;if not coalesce(settings.module_enabled,false) then raise exception 'Le système de punch est désactivé' using errcode='42501';end if;
 select * into shift from punch_shifts where organization_id=org and employee_id=actor and ended_at is null for update;select nullif(payload->>'latitude','')::numeric,nullif(payload->>'longitude','')::numeric into lat,lon;
 if job is not null then select mir_core.punch_distance_m(lat,lon,j.latitude,j.longitude) into dist from jobs j where j.organization_id=org and j.id=job and mir_core.job_allowed(org,j.id,actor);if not found then raise exception 'Job non autorisée' using errcode='42501';end if;end if;zone:=case when not settings.gps_enabled then 'unknown' when lat is null then 'unavailable' when dist is null then 'unknown' when settings.radius_m is null or dist<=settings.radius_m then 'inside' else 'outside' end;
 if settings.gps_required and lat is null then raise exception 'Position GPS requise';end if;if zone='outside' and settings.outside_policy='block' then raise exception 'Punch hors zone bloqué';end if;if zone='outside' and settings.outside_reason_required and btrim(coalesce(payload->>'outsideReason',''))='' then raise exception 'Justification hors zone requise';end if;
 if action='in' then if shift.id is not null then raise exception 'Un punch est déjà actif';end if;insert into punch_shifts(organization_id,employee_id,work_date,started_at,source,device_id) values(org,actor,now_at,now_at,source_name,left(coalesce(payload->>'deviceId',''),160)) returning * into shift;insert into punch_segments(organization_id,shift_id,job_id,segment_type,started_at,created_by) values(org,shift.id,job,'job',now_at,actor) returning * into segment;
 elsif action in('switch','travel_start','travel_arrive') then if shift.id is null then raise exception 'PUNCH IN requis';end if;update punch_segments set ended_at=now_at where organization_id=org and shift_id=shift.id and ended_at is null;if action='travel_start' then insert into punch_segments(organization_id,shift_id,job_id,next_job_id,segment_type,started_at,created_by) values(org,shift.id,coalesce((select job_id from punch_segments where organization_id=org and shift_id=shift.id order by started_at desc limit 1),job),job,'travel',now_at,actor) returning * into segment;else insert into punch_segments(organization_id,shift_id,job_id,segment_type,started_at,created_by) values(org,shift.id,job,'job',now_at,actor) returning * into segment;end if;
 elsif action='out' then if shift.id is null then raise exception 'Aucun punch actif';end if;update punch_segments set ended_at=now_at where organization_id=org and shift_id=shift.id and ended_at is null;update punch_shifts set ended_at=now_at,status=case when zone='outside' then 'review' else 'review' end,auto_break_minutes=case when settings.auto_break_enabled and extract(epoch from(now_at-shift.started_at))/60>=settings.break_threshold_minutes then settings.break_minutes else 0 end where organization_id=org and id=shift.id returning * into shift;
 else raise exception 'Action punch inconnue';end if;
 insert into punch_events(organization_id,shift_id,employee_id,job_id,event_type,request_id,original_at,latitude,longitude,accuracy_m,distance_m,zone_status,outside_reason,device_id,source,payload) values(org,shift.id,actor,job,action,$2,nullif(payload->>'originalAt','')::timestamptz,lat,lon,nullif(payload->>'accuracy','')::numeric,dist,zone,coalesce(payload->>'outsideReason',''),left(coalesce(payload->>'deviceId',''),160),source_name,payload) on conflict on constraint punch_events_organization_id_employee_id_request_id_key do nothing;
 insert into punch_audit(organization_id,actor_id,employee_id,action,entity_type,entity_id,payload) values(org,actor,actor,action,'shift',shift.id,payload);return jsonb_build_object('ok',true,'serverAt',now_at,'shiftId',shift.id,'zone',zone,'distanceM',dist);end$$;

create function public.mir_punch_correction(org uuid,correction uuid default null,payload jsonb default '{}') returns uuid language plpgsql security definer set search_path=pg_catalog,mir_core as $$declare result uuid:=coalesce(correction,gen_random_uuid());c punch_corrections;r text:=mir_core.staff_role(org);decision text:=payload->>'decision';begin
 if correction is null then insert into punch_corrections(organization_id,id,employee_id,shift_id,correction_type,proposed_at,proposed_job_id,explanation,attachment_path,proposed_data) values(org,result,auth.uid(),nullif(payload->>'shiftId','')::uuid,payload->>'type',nullif(payload->>'proposedAt','')::timestamptz,nullif(payload->>'jobId','')::uuid,payload->>'explanation',nullif(payload->>'attachmentPath',''),payload);insert into punch_audit(organization_id,actor_id,employee_id,action,entity_type,entity_id,payload) values(org,auth.uid(),auth.uid(),'correction_request','correction',result,payload);return result;end if;
 if not mir_core.punch_manager(org) then raise exception 'Approbateur requis' using errcode='42501';end if;select * into c from punch_corrections where organization_id=org and id=correction for update;if c.id is null or c.employee_id=auth.uid() then raise exception 'Auto-approbation interdite' using errcode='42501';end if;if c.changes_overtime and r not in('boss','admin') then raise exception 'Boss requis pour les heures supplémentaires' using errcode='42501';end if;if decision not in('approved','refused','clarification') or btrim(coalesce(payload->>'reason',''))='' then raise exception 'Décision et motif requis';end if;update punch_corrections set status=decision,decided_by=auth.uid(),decision_reason=payload->>'reason',decided_at=now() where organization_id=org and id=correction;insert into punch_audit(organization_id,actor_id,employee_id,action,entity_type,entity_id,reason,payload) values(org,auth.uid(),c.employee_id,'correction_'||decision,'correction',correction,payload->>'reason',payload);return result;end$$;

create function public.mir_punch_admin(org uuid,action text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path=pg_catalog,mir_core as $$declare r text:=mir_core.staff_role(org);period uuid;begin if r not in('admin','boss') then raise exception 'Admin ou Boss requis' using errcode='42501';end if;
 if action='settings' then insert into punch_settings(organization_id,module_enabled,gps_enabled,gps_required,radius_m,outside_policy,outside_reason_required,offline_enabled,auto_break_enabled,break_threshold_minutes,break_minutes,travel_rule,bank_enabled,bank_multiplier,updated_by) values(org,coalesce((payload->>'enabled')::boolean,false),coalesce((payload->>'gpsEnabled')::boolean,true),coalesce((payload->>'gpsRequired')::boolean,false),nullif(payload->>'radiusM','')::int,coalesce(payload->>'outsidePolicy','review'),coalesce((payload->>'outsideReasonRequired')::boolean,true),coalesce((payload->>'offlineEnabled')::boolean,true),coalesce((payload->>'autoBreakEnabled')::boolean,true),coalesce((payload->>'breakThresholdMinutes')::int,300),coalesce((payload->>'breakMinutes')::int,15),coalesce(payload->>'travelRule','separate'),coalesce((payload->>'bankEnabled')::boolean,false),coalesce((payload->>'bankMultiplier')::numeric,1),auth.uid()) on conflict(organization_id) do update set module_enabled=excluded.module_enabled,gps_enabled=excluded.gps_enabled,gps_required=excluded.gps_required,radius_m=excluded.radius_m,outside_policy=excluded.outside_policy,outside_reason_required=excluded.outside_reason_required,offline_enabled=excluded.offline_enabled,auto_break_enabled=excluded.auto_break_enabled,break_threshold_minutes=excluded.break_threshold_minutes,break_minutes=excluded.break_minutes,travel_rule=excluded.travel_rule,bank_enabled=excluded.bank_enabled,bank_multiplier=excluded.bank_multiplier,updated_by=auth.uid(),updated_at=now();
 elsif action in('lock_period','reopen_period') then if btrim(coalesce(payload->>'reason',''))='' then raise exception 'Motif requis';end if;period:=(payload->>'periodId')::uuid;update time_periods set status=case when action='lock_period' then 'locked' else 'reopened' end,locked_by=auth.uid(),locked_at=now(),reopen_reason=payload->>'reason' where organization_id=org and id=period;
 else raise exception 'Action admin inconnue';end if;insert into punch_audit(organization_id,actor_id,action,entity_type,entity_id,reason,payload) values(org,auth.uid(),action,case when action='settings' then 'settings' else 'period' end,period,coalesce(payload->>'reason',''),payload);return jsonb_build_object('ok',true);end$$;
revoke all on function public.mir_punch_snapshot(uuid,uuid),public.mir_punch_action(uuid,uuid,text,uuid,jsonb),public.mir_punch_correction(uuid,uuid,jsonb),public.mir_punch_admin(uuid,text,jsonb) from public,anon;grant execute on function public.mir_punch_snapshot(uuid,uuid),public.mir_punch_action(uuid,uuid,text,uuid,jsonb),public.mir_punch_correction(uuid,uuid,jsonb),public.mir_punch_admin(uuid,text,jsonb) to authenticated;
commit;
